 "content": "def transform(grid):
    """Complete vertical gap-columns between aligned horizontal stripe segments."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A stripe row contains substantial horizontal structure; isolated vertical
    # marker runs below the field are deliberately not classified as stripes.
    stripe_rows = [r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 5]
    triggers = {}
    for r in stripe_rows:
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if grid[r][c] == 0 and color != 0 and grid[r][c + 1] == color:
                triggers.setdefault(c, []).append((r, color))

    for c, marks in triggers.items():
        marks.sort()
        previous = -1
        for r, color in marks:
            # Each stripe's gap color occupies the band above it, starting
            # immediately after the preceding stripe gap in this column.
            for rr in range(previous + 1, r + 1):
                out[rr][c] = color
            previous = r

        # A vertical marker below the last stripe extends upward to that stripe.
        below = [r for r in range(previous + 1, h) if grid[r][c] != 0]
        if below:
            first = below[0]
            marker_color = grid[first][c]
            for rr in range(previous + 1, first):
                out[rr][c] = marker_color

    return out
